    ld (current_behavior_map), hl
    ld a, BEHAVIOR_SCREEN1_0_DATA_BANK
    ld (current_behavior_map_bank), a
    ld a, l
    ld (behavior_cache_map_l), a
    ld a, h
    ld (behavior_cache_map_h), a
    ld a, #FF
    ld (behavior_cache_row), a
    ret


